#include <stdio.h>
#include <stdlib.h>

int gvar = 66;              // .data  (initialized global)
int ugvar;                  // .bss   (zero-initialized global)
const int cgvar = 1010;     // .rodata (const global)

void foo(void) {            // .text  (code)
    int lvar = 1;           // stack
    printf("lvar   %p\n", (void *)&lvar);
}

int main(void) {
    static int counter = 5; // .data  (static local, initialized)
    static int zeroed;      // .bss   (static local, uninitialized)
    int *hvar = malloc(sizeof *hvar);   // pointer on stack, block on heap
    printf("foo    %p\n", (void *)&foo);
    printf("cgvar  %p\n", (void *)&cgvar);
    printf("gvar   %p\n", (void *)&gvar);
    printf("ugvar  %p\n", (void *)&ugvar);
    printf("heap   %p\n", (void *)hvar);
    foo();
    free(hvar);
    return (counter + zeroed) & 0;
}

void *start = sbrk(0);        // current program break (POSIX)
char *p = malloc(100);        // may or may not move the break
printf("%p -> %p\n", start, sbrk(0));

int sum(int n) {          // each call adds a frame: n, return address, saved regs
    if (n == 0) return 0;
    return n + sum(n - 1);
}                         // sum(100000) can exhaust an 8 MiB stack

